        // ═════════════════════════ topology ═════════════════════════

        // The side that opens the session.
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Initiator : Host { }

        // The side that accepts the session.
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Acceptor : Host { }

        interface Session : Connects<Initiator, Acceptor> {
            // Every SBE message, either direction; composites and typedefs stay sub-packs.
            [_____lr_____<(ChannelReset4, AdminHeartbeat12, AdminLogin15, AdminLogout16, MDInstrumentDefinitionFuture27, MDInstrumentDefinitionSpread29, SecurityStatus30, MDIncrementalRefreshBook32, MDIncrementalRefreshDailyStatistics33, MDIncrementalRefreshLimitsBanding34, MDIncrementalRefreshSessionStatistics35, MDIncrementalRefreshVolume37, SnapshotFullRefresh38, QuoteRequest39, MDInstrumentDefinitionOption41, MDIncrementalRefreshTradeSummary42, MDIncrementalRefreshOrderBook43, SnapshotFullRefreshOrderBook44, MDIncrementalRefreshBook46, MDIncrementalRefreshOrderBook47, MDIncrementalRefreshTradeSummary48, MDIncrementalRefreshDailyStatistics49, MDIncrementalRefreshLimitsBanding50, MDIncrementalRefreshSessionStatistics51, SnapshotFullRefresh52, SnapshotFullRefreshOrderBook53, MDInstrumentDefinitionFuture54, MDInstrumentDefinitionOption55, MDInstrumentDefinitionSpread56)>]
            struct Established { }
        }

